package com.splitmate.repo; import com.splitmate.domain.Expense; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.List; public interface ExpenseRepository extends JpaRepository<Expense,Long>{@Query("select e from Expense e where e.householdId=:hid and (:category is null or upper(e.category)=upper(:category)) order by e.expenseDate desc,e.id desc") Page<Expense> findHouseholdExpenses(@Param("hid") Long householdId,@Param("category") String category,Pageable pageable);List<Expense> findByHouseholdId(Long householdId);}
